CREATE TABLE users (id INTEGER PRIMARY KEY, uid TEXT NOT NULL UNIQUE, lp_id TEXT NOT NULL UNIQUE, username TEXT, mobile TEXT UNIQUE, email TEXT UNIQUE, open_id TEXT UNIQUE, password TEXT, avatar_file_id INTEGER, background_file_id INTEGER, sex INTEGER NOT NULL DEFAULT 0, birthday DATETIME, city TEXT, job TEXT, company TEXT, signature TEXT, website TEXT, freezed BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE files (id INTEGER PRIMARY KEY, uid TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, name TEXT NOT NULL, path TEXT, type TEXT NOT NULL, file_md5 TEXT NOT NULL, size INTEGER NOT NULL, key TEXT NOT NULL UNIQUE, extension TEXT, width INTEGER, height INTEGER, blurhash TEXT, arthash TEXT, arthash_codec TEXT, lng REAL, lat REAL, country TEXT, country_code TEXT, province TEXT, city TEXT, district TEXT, address TEXT, altitude REAL, taken_at DATETIME, device_make TEXT, device_model TEXT, lens_model TEXT, f_number TEXT, exposure_time TEXT, iso INTEGER, focal_length TEXT, exif_raw BLOB, duration REAL, codec TEXT, bitrate INTEGER, frame_rate REAL, video_metadata BLOB, transcoding_task_id TEXT, is_private BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE permission_spaces (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE permissions (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, space_id INTEGER NOT NULL, position INTEGER NOT NULL, value INTEGER NOT NULL, module TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE roles (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, is_system BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE user_roles (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, role_id INTEGER NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE(user_id, role_id));
CREATE TABLE role_permissions (id INTEGER PRIMARY KEY, role_id INTEGER NOT NULL, permission_id INTEGER NOT NULL, space_id INTEGER NOT NULL, value INTEGER NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE(role_id, permission_id));
CREATE TABLE user_permission_caches (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, space_id INTEGER NOT NULL, value INTEGER NOT NULL, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE(user_id, space_id));
CREATE TABLE multipart_uploads (id INTEGER PRIMARY KEY, upload_id TEXT NOT NULL UNIQUE, key TEXT NOT NULL, md5 TEXT NOT NULL, file_name TEXT NOT NULL, file_size INTEGER NOT NULL, content_type TEXT, total_parts INTEGER NOT NULL, chunk_size INTEGER NOT NULL, user_id INTEGER, status TEXT NOT NULL DEFAULT 'initiated', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE uploaded_parts (id INTEGER PRIMARY KEY, upload_id TEXT NOT NULL, part_number INTEGER NOT NULL, e_tag TEXT NOT NULL, size INTEGER NOT NULL, created_at DATETIME NOT NULL, UNIQUE(upload_id, part_number));
CREATE TABLE colors (id INTEGER PRIMARY KEY, hex TEXT NOT NULL UNIQUE, r INTEGER, g INTEGER, b INTEGER, created_at DATETIME NOT NULL);
CREATE TABLE file_colors (id INTEGER PRIMARY KEY, file_id INTEGER NOT NULL, color_id INTEGER NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, rank INTEGER NOT NULL DEFAULT 0, percentage REAL, created_at DATETIME NOT NULL, UNIQUE(file_id, color_id));
CREATE TABLE video_variants (id INTEGER PRIMARY KEY, file_id INTEGER NOT NULL, quality TEXT NOT NULL, key TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'mp4', size INTEGER, width INTEGER, height INTEGER, bitrate INTEGER, fps INTEGER, duration REAL, created_at DATETIME NOT NULL);
CREATE TABLE transcoding_tasks (id INTEGER PRIMARY KEY, task_id TEXT NOT NULL UNIQUE, file_id INTEGER, source_url TEXT NOT NULL, webhook_url TEXT, provider TEXT NOT NULL DEFAULT 'aliyun_mps', status TEXT NOT NULL, resolutions BLOB, external_job_ids BLOB, results BLOB, error_msg TEXT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, completed_at DATETIME, deleted_at DATETIME);
